import os,glob,json,tarfile,hashlib,subprocess,re
root='/opt/dsh-src-015'
# map package name -> built dir
built={}
for mf in glob.glob(root+'/packages/*/*/package.json')+glob.glob(root+'/apps/*/package.json'):
    try: j=json.load(open(mf))
    except: continue
    n=j.get('name'); v=j.get('version')
    if n and n.startswith('@deepseek-ai/') and v=='0.1.5-alpha.1':
        built[n]=os.path.dirname(mf)
print('built official pkgs:',len(built))
import random
random.seed(7)
sample=random.sample(sorted(built), 12)
def md5(p):
    h=hashlib.md5()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(1<<20),b''): h.update(b)
    return h.hexdigest()
res=[]
for n in sample:
    short=n.split('/')[-1]
    tgz=f'/tmp/idcmp/{short}.tgz'
    url=f'http://127.0.0.1:4873/{n.replace("/","%2f")}/-/{short}-0.1.5-alpha.1.tgz'
    r=subprocess.run(['curl','-sS','-m','40','-o',tgz,url],capture_output=True)
    try:
        with tarfile.open(tgz) as t:
            members={m.name:m for m in t.getmembers() if m.isfile()}
            # compare lib/index.js and package.json
            out=[]
            for rel in ('package/lib/index.js','package/package.json'):
                if rel in members:
                    data=t.extractfile(members[rel]).read()
                    out.append((rel,hashlib.md5(data).hexdigest(),len(data)))
            local_js=os.path.join(built[n],'lib/index.js')
            local_pkg=os.path.join(built[n],'package.json')
            cmp=[]
            if os.path.exists(local_js) and out and out[0][0]=='package/lib/index.js':
                cmp.append(('lib/index.js', out[0][1]==md5(local_js)))
            if os.path.exists(local_pkg) and len(out)>1:
                cmp.append(('package.json', out[1][1]==md5(local_pkg)))
            res.append((n,cmp))
    except Exception as e:
        res.append((n,[('err',str(e)[:40])]))
for n,c in res:
    print(n, c)
EOF

