// Register —— 挂载本模块全部 /api/sessions... 路由。
func Register(mux *http.ServeMux, d *center.Deps) {
	// W230：GET /api/sessions（单实例列表）退役——前端全走 /api/ai/sessions 聚合面
	// （W225 审计 §3.2：聚合面已接管，前端零用本路由）。

	// 消息（本机直读）
	mux.HandleFunc("GET /api/sessions/{id}/messages", func(w http.ResponseWriter, r *http.Request) {
		inst := instanceOf(d.Cfg, r.URL.Query(), nil)
		if !inst.ok {
			apix.Err(w, http.StatusBadRequest, inst.error)
			return
		}
		limit := defaultLimit
		if v := r.URL.Query().Get("limit"); v != "" {
			if n, err := strconv.ParseFloat(v, 64); err == nil {
				limit = NormalizeLimit(n)
			}
		}
		// W124b 向前翻页（懒加载历史）：before=<seq>（正整数 TimelineItem.seq）→ 返回 seq<before 的
		// 最近 limit 条；缺省/非法（非正数/非数字）→ 维持「尾部最近 N 条」（W128 缓存路径）。
		before := 0
		if v := r.URL.Query().Get("before"); v != "" {
			if n, err := strconv.ParseInt(v, 10, 64); err == nil && n > 0 {
				before = int(n)
			}
		}
		// W124h：撤回标记过滤（基线 /messages；live 增量 realtime/SSE 本轮不动）
		id := r.PathValue("id")
		var res SessionTailResult
		if before > 0 {
			res = sessionMessagesBefore(id, limit, inst.sessionsDir, before)
		} else {
			res = sessionMessagesCached(id, limit, inst.sessionsDir)
		}
		res.Messages = applyRetractions(res.Messages, inst.sessionsDir, id)
		apix.WriteJSON(w, http.StatusOK, res)
	})

	// —— W124c：会话状态栏（上下文占用/模型/effort/预设/token 速率）——
	mux.HandleFunc("GET /api/sessions/{id}/meta", func(w http.ResponseWriter, r *http.Request) {
