#!/usr/bin/env bash
# 0.1.5 预检：自定义 preset 的 persona 配置能否被 0.1.5 的 schema 接受
set -u
LOG=/tmp/3180-015-presetcheck.log
exec >"$LOG" 2>&1
export HOME=/root
export PATH=/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin
cd /opt/dsh/profiles/web || exit 90
node --input-type=module - <<'JS'
import { readFileSync } from 'node:fs'
import yaml from 'js-yaml'
const mod = await import('@deepseek-ai/dsh-persona')
const Config = mod.Config ?? mod.default?.Config
if (!Config) { console.log('Config export 未找到; keys:', Object.keys(mod).slice(0, 25)); process.exit(0) }
for (const p of ['code', 'router-spec', 'router-standard']) {
  const doc = yaml.load(readFileSync(`/opt/dsh/.agent-presets/${p}/agent.cordis.yml`, 'utf8'))
  const row = doc.find(r => r && r.id === 'persona')
  if (!row) { console.log(p.padEnd(16), 'NO persona row'); continue }
  try {
    const out = Config(row.config)
    console.log(p.padEnd(16), 'PASS', 'prefix.len=' + String(out.prefix.length), 'suffix.len=' + String(String(out.suffix ?? '').length))
  } catch (e) { console.log(p.padEnd(16), 'FAIL', String(e.message).slice(0, 200)) }
}
JS
echo "exit=$?"

#!/usr/bin/env bash
# 0.1.5 预检：自定义 preset 的 persona 配置能否被 0.1.5 的 schema 接受（容忍 !!js 标签）
set -u
LOG=/tmp/3180-015-presetcheck.log
exec >"$LOG" 2>&1
export HOME=/root
export PATH=/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin
cd /opt/dsh/profiles/web || exit 90
node --input-type=module - <<'JS'
import { readFileSync } from 'node:fs'
import yaml from 'js-yaml'
const JsTag = new yaml.Type('tag:yaml.org,2002:js', {
  kind: 'scalar',
  resolve: () => true,
  construct: data => ({ __js: data }),
})
const schema = yaml.DEFAULT_SCHEMA.extend([JsTag])
const mod = await import('@deepseek-ai/dsh-persona')
const Config = mod.Config ?? mod.default?.Config
if (!Config) { console.log('Config export 未找到; keys:', Object.keys(mod).slice(0, 25)); process.exit(0) }
for (const p of ['code', 'router-spec', 'router-standard']) {
  let doc
  try { doc = yaml.load(readFileSync(`/opt/dsh/.agent-presets/${p}/agent.cordis.yml`, 'utf8'), { schema }) }
  catch (e) { console.log(p.padEnd(16), 'YAML_FAIL', String(e.message).slice(0, 120)); continue }
  const rows = Array.isArray(doc) ? doc : []
  const row = rows.find(r => r && r.id === 'persona')
  if (!row) { console.log(p.padEnd(16), 'NO persona row'); continue }
  try {
    const out = Config(row.config)
    console.log(p.padEnd(16), 'PASS', 'prefix.len=' + String(out.prefix.length), 'suffix.len=' + String(String(out.suffix ?? '').length), 'complete=' + String(out.complete))
  } catch (e) { console.log(p.padEnd(16), 'FAIL', String(e.message).slice(0, 200)) }
}
JS
echo "exit=$?"
